old=p.read_text(); new='''def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = []
    for c in range(w):
        counts = {}
        for r in range(h):
            v = grid[r][c]
            if v: counts[v] = counts.get(v, 0) + 1
        vals.append(max(counts, key=counts.get))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = vals[c-1] if r == c and c > 0 else vals[c]
    return out
'''; p.write_text(new)
